local here=(arg and arg[0]or""):match("^(.*)[/\\][^/\\]+$")or"."package.path=here.."/?.lua;"..here.."/?/init.lua;"..here.."/../../?.lua;"..here.."/../../?/init.lua;"..package.path io.stdout:setvbuf("no")local app=require("setup.app")local socket=require("socket")local function readAsset(name)local f=assert(io.open(here.."/setup/panel/"..name,"rb"))local s=f:read("*a")f:close()return s end local opts=app.parse(arg or{})if opts.help or opts.bad then print(app.USAGE)os.exit(opts.help and 0 or 1)end local ok,runner=pcall(app.start,opts,readAsset)if not ok then print("Error: "..(type(runner)=="table"and runner.message or tostring(runner)))os.exit(1)end while not runner.poll()do socket.sleep(0.02)end
